class TorrentParser{constructor(){this.pos=0}async parseTorrentFile(e){if(100!==e[0])throw new Error("Invalid torrent file format");const t=this.decodeBencode(e);if(!t.info)throw new Error("No info section found in torrent");const n=this.encodeBencode(t.info),o=await this.sha1(n),r=this.bytesToHex(o);let s="";t.info.name&&(s=(new TextDecoder).decode(t.info.name));const i=[];if(t.announce)try{const e=(new TextDecoder).decode(t.announce);this.isValidTrackerUrl(e)&&i.push(e)}catch(e){}if(t["announce-list"]&&Array.isArray(t["announce-list"]))for(const e of t["announce-list"])if(Array.isArray(e))for(const t of e)if(t instanceof Uint8Array)try{const e=(new TextDecoder).decode(t);this.isValidTrackerUrl(e)&&!i.includes(e)&&i.push(e)}catch(e){}let c=`magnet:?xt=urn:btih:${r}`;s&&(c+=`&dn=${encodeURIComponent(s)}`);for(let e=0;e<Math.min(i.length,15);e++)try{c+=`&tr=${encodeURIComponent(i[e])}`}catch(e){}return c}isValidTrackerUrl(e){try{const t=new URL(e);return["http:","https:","udp:"].includes(t.protocol)}catch(e){return!1}}decodeBencode(e){this.pos=0;const t=()=>{if(this.pos>=e.length)throw new Error("Unexpected end of data");const n=e[this.pos];if(n>=48&&n<=57)return this.decodeString(e);if(105===n)return this.decodeInteger(e);if(108===n)return this.decodeList(e,t);if(100===n)return this.decodeDictionary(e,t);throw new Error(`Invalid bencode at position ${this.pos}`)};return t()}decodeString(e){const t=e.indexOf(58,this.pos);if(-1===t)throw new Error("Invalid string length");const n=(new TextDecoder).decode(e.slice(this.pos,t)),o=parseInt(n,10);this.pos=t+1;const r=e.slice(this.pos,this.pos+o);return this.pos+=o,r}decodeInteger(e){this.pos++;const t=e.indexOf(101,this.pos);if(-1===t)throw new Error("Invalid integer");const n=(new TextDecoder).decode(e.slice(this.pos,t));return this.pos=t+1,parseInt(n,10)}decodeList(e,t){this.pos++;const n=[];for(;101!==e[this.pos];)n.push(t());return this.pos++,n}decodeDictionary(e,t){this.pos++;const n={};for(;101!==e[this.pos];){const o=(new TextDecoder).decode(this.decodeString(e)),r=t();n[o]=r}return this.pos++,n}bytesToHex(e){return Array.from(e).map((e=>e.toString(16).padStart(2,"0"))).join("")}async sha1(e){const t=await crypto.subtle.digest("SHA-1",e);return new Uint8Array(t)}encodeBencode(e){if(e instanceof Uint8Array){const t=(new TextEncoder).encode(e.length.toString()),n=new Uint8Array(t.length+1+e.length);return n.set(t,0),n[t.length]=58,n.set(e,t.length+1),n}if("number"==typeof e){const t=`i${e}e`;return(new TextEncoder).encode(t)}if(Array.isArray(e)){const t=[new Uint8Array([108])];for(const n of e)t.push(this.encodeBencode(n));t.push(new Uint8Array([101]));const n=t.reduce(((e,t)=>e+t.length),0),o=new Uint8Array(n);let r=0;for(const e of t)o.set(e,r),r+=e.length;return o}if("object"==typeof e){const t=[new Uint8Array([100])],n=Object.keys(e).sort();for(const o of n){const n=(new TextEncoder).encode(o);t.push(this.encodeBencode(n)),t.push(this.encodeBencode(e[o]))}t.push(new Uint8Array([101]));const o=t.reduce(((e,t)=>e+t.length),0),r=new Uint8Array(o);let s=0;for(const e of t)r.set(e,s),s+=e.length;return r}throw new Error("Unsupported type for bencode encoding")}}window.TorrentParser=TorrentParser;